//! Reference data for the calculations: physical constants and the HMRC gravity table.
//!
//! Generated by `tools/extract-calc-data.py` from `src/calculations/Algorithms.cpp` and
//! `src/measurement/PhysicalConstants.h`, and embedded at compile time.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct CalculationData {
    pub generated_by: String,
    pub source_files: Vec<String>,
    /// Atomic weights, densities and the like, by the name the C++ gives them.
    pub physical_constants: BTreeMap<String, f64>,
    pub gravity_difference_factors: Vec<GravityDifferenceFactor>,
}

/// One row of HM Revenue and Customs' table for turning a drop in gravity into alcohol by volume.
///
/// The gravity differences are multiplied by ten so that they are whole numbers, exactly as the
/// C++ does.
#[derive(Debug, Clone, Copy, Deserialize)]
pub struct GravityDifferenceFactor {
    pub excess_gravity_diff_x10_min: f64,
    pub excess_gravity_diff_x10_max: f64,
    pub pct_abv_min: f64,
    pub pct_abv_max: f64,
    pub factor: f64,
}

const CALCULATIONS_JSON: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../schema/calculations.json"));

/// The calculation reference data, parsed once.
///
/// # Panics
///
/// If the embedded JSON does not match these types.
pub fn calculation_data() -> &'static CalculationData {
    static DATA: OnceLock<CalculationData> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(CALCULATIONS_JSON).expect("schema/calculations.json does not match CalculationData")
    })
}

/// A physical constant by the name `src/measurement/PhysicalConstants.h` gives it.
///
/// # Panics
///
/// If there is no such constant, which would be a typo rather than a runtime condition.
pub fn constant(name: &str) -> f64 {
    calculation_data().physical_constants[name]
}
